function normalizar(str) {
  return str.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^\w\s\.]/g, ' ');
}

// ── CLASIFICACIÓN POR ENCABEZADO (solo primeros 500 caracteres) ──
function identificarTipoDocumento(textoCompleto) {
  const encabezado = textoCompleto.substring(0, 500);
  const encabezadoNorm = normalizar(encabezado);

  // Nota de Presentación
  if (encabezadoNorm.includes('motivo del tramite') ||
      encabezadoNorm.includes('direccion de evaluacion y control de biologicos') ||
      encabezadoNorm.includes('se dirige a ud') ||
      encabezadoNorm.includes('solicitar autorizacion')) {
    return 'nota';
  }

  // Formulario de Solicitud
  // FIX #2: se agregaron variantes de encabezado reales ("Ficha de Modificaciones",
  // "Modificación de aprobación anterior") porque el PDF real no usa el texto
  // "1.2 Formulario de solicitud" en el encabezado y el documento quedaba sin clasificar.
  if (encabezadoNorm.includes('1.2 formulario de solicitud') ||
      encabezadoNorm.includes('antecedentes y descripcion de los cambios') ||
      encabezadoNorm.includes('autorizado vs propuesto') ||
      encabezadoNorm.includes('ficha de modificaciones') ||
      encabezadoNorm.includes('modificacion de aprobacion anterior')) {
    return 'formulario';
  }

  // Declaración Jurada
  if (encabezadoNorm.includes('declaracion jurada') ||
      (encabezadoNorm.includes('datos generales') && encabezadoNorm.includes('tipo de tramite'))) {
    return 'declaracion';
  }

  return null; // Documento no reconocido (como el poema)
}

// ── VERIFICACIÓN DE DOCUMENTOS OBLIGATORIOS (SIEMPRE ACTIVA) ──
function verificarDocumentos(listaDocs) {
  const tiposEncontrados = new Set(
    listaDocs.map(d => identificarTipoDocumento(d.text || '')).filter(Boolean)
  );

  const requeridos = [
    { tipo: 'nota', nombre: 'Nota de Presentación (Módulo 1.0)' },
    { tipo: 'formulario', nombre: 'Formulario de Solicitud (Módulo 1.2)' },
    { tipo: 'declaracion', nombre: 'Declaración Jurada (Documento declarado por el regulado)' }
  ];

  return requeridos.filter(r => !tiposEncontrados.has(r.tipo)).map(r => r.nombre);
}

// ── VERIFICAR SI HAY DOCUMENTOS NO RECONOCIDOS ──
function hayDocumentosInvalidos(listaDocs) {
  return listaDocs.filter(d => identificarTipoDocumento(d.text || '') === null);
}

// ── EXTRACCIÓN DE DATOS ──
function extraerDeDocumentos(listaDocs, tipoDoc, patron) {
  const doc = listaDocs.find(d => identificarTipoDocumento(d.text || '') === tipoDoc);
  if (!doc) return '';
  const match = doc.text.match(patron);
  return match ? match[1].trim() : '';
}

// FIX #1: el motivo puede venir partido en varias líneas dentro del PDF
// (ej. "Modificación de\nenvases y/o presentación de expendio."). Antes el regex
// cortaba en el primer salto de línea. Ahora captura todo hasta "N° RECIBO"
// o hasta una línea en blanco, y luego colapsa los saltos de línea en espacios.
function extraerMotivo(listaDocs) {
  const nota = listaDocs.find(d => identificarTipoDocumento(d.text || '') === 'nota');
  if (!nota) return '';
  const match = nota.text.match(/MOTIVO DEL TRÁMITE:\s*([\s\S]+?)(?:\n\s*N°\s*RECIBO|\r?\n\r?\n|$)/i);
  if (match) {
    return match[1].replace(/\s*\n\s*/g, ' ').trim();
  }
  return '';
}

function extraerEmpresa(listaDocs) {
  const dj = listaDocs.find(d => identificarTipoDocumento(d.text || '') === 'declaracion');
  if (!dj) return '';
  const match = dj.text.match(/Laboratorio:\s*([^\n]+)/i);
  return match ? match[1].trim() : '';
}

function extraerProducto(listaDocs) {
  const dj = listaDocs.find(d => identificarTipoDocumento(d.text || '') === 'declaracion');
  if (!dj) return '';
  const match = dj.text.match(/Nombre comercial:\s*([^\n]+)/i);
  return match ? match[1].trim() : '';
}

// ── VERIFICACIÓN DE COHERENCIA ──
function verificarCoherencia(listaDocs) {
  const productos = new Set();
  const empresas = new Set();

  listaDocs.forEach(doc => {
    const tipo = identificarTipoDocumento(doc.text || '');
    if (tipo === 'nota' || tipo === 'formulario' || tipo === 'declaracion') {
      const producto = extraerProducto([doc]);
      const empresa = extraerEmpresa([doc]);
      if (producto) productos.add(producto.toUpperCase());
      if (empresa) empresas.add(empresa.toUpperCase());
    }
  });

  return {
    coherente: productos.size <= 1 && empresas.size <= 1,
    productos: Array.from(productos),
    empresas: Array.from(empresas)
  };
}

function clasificarTramite(motivo) {
  const t = normalizar(motivo);
  if (t.includes('nuevo acondicionador')) return 'Nuevo acondicionador secundario';
  if (t.includes('metodo analitico') || t.includes('procedimiento analitico')) return 'Cambio en método analítico';
  if (t.includes('metodo de elaboracion')) return 'Autorización de método de elaboración';
  if (t.includes('nueva presentacion')) return 'Autorización de nueva presentación';
  if (t.includes('prospecto') || t.includes('rotulo')) return 'Modificación de prospecto/rótulo';
  if (t.includes('nueva indicacion') || t.includes('indicacion terapeutica')) return 'Nueva indicación terapéutica';
  if (t.includes('especificaci') && (t.includes('cambio') || t.includes('modificaci'))) return 'Cambio en especificaciones';
  if (t.includes('registro inicial') || t.includes('solicitud de registro')) return 'Registro inicial';
  if (t.includes('fabricante') && t.includes('cambio')) return 'Cambio de fabricante';
  if (t.includes('variacion menor')) return 'Variación menor';
  return 'Modificación post-registro';
}

// ── EJECUCIÓN DE VALIDACIONES ──
const docsFaltantes = verificarDocumentos(agregado.data || []);
const docsInvalidos = hayDocumentosInvalidos(agregado.data || []);
const motivoExtraido = extraerMotivo(agregado.data || []);
const empresaExtraida = extraerEmpresa(agregado.data || []);
const productoExtraido = extraerProducto(agregado.data || []);
const coherencia = verificarCoherencia(agregado.data || []);

const motivoClasificado = clasificarTramite(motivoExtraido);
const motivoFinal = motivoExtraido || motivoClasificado || 'Modificación post-registro';

const producto = productoExtraido || 'NO IDENTIFICADO';
const empresa = empresaExtraida || 'NO IDENTIFICADO';

// ── DECISIÓN FINAL ──
const hayDocsFaltantes = docsFaltantes.length > 0;
const hayDocsInvalidos = docsInvalidos.length > 0;
const hayIncoherencia = !coherencia.coherente;
const esObjecion = hayDocsFaltantes || hayDocsInvalidos || hayIncoherencia;

let detalle = '';
if (hayDocsFaltantes) {
  detalle = `Documentos obligatorios faltantes: ${docsFaltantes.join('; ')}.`;
} else if (hayDocsInvalidos) {
  detalle = `Se detectaron ${docsInvalidos.length} documento(s) no reconocido(s) como parte de la documentación regulatoria. Verifique que todos los archivos sean documentos válidos del expediente.`;
} else if (hayIncoherencia) {
  detalle = `Incoherencia entre documentos. Productos encontrados: ${coherencia.productos.join(', ')}. Empresas encontradas: ${coherencia.empresas.join(', ')}.`;
}

return [{
  json: {
    resultado: esObjecion ? 'OBJECION' : 'VALIDACION',
    nombreArchivo: esObjecion ? `informe_objecion_${timestamp}.docx` : `informe_validacion_${timestamp}.docx`,
    plantillaKey: esObjecion ? 'objecion' : 'aceptable',
    DIA: pad(ahora_art.getUTCDate()),
    MES: meses[ahora_art.getUTCMonth()],
    TIMESTAMP: timestampLegible,
    EXPEDIENTE: expedienteForm || 'PENDIENTE DE CARGA EN FORMULARIO',
    MOTIVO: motivoFinal,
    PRODUCTO: producto,
    EMPRESA: empresa,
    DETALLE: detalle,
    respuestaIA: respuesta
  }
}];

